using System;using System.IO;using System.Linq;using System.Text;using System.Windows.Forms;
namespace GearLab {public static partial class RobotCad {
 static void BuildReference67(RobotBuild b,RobotJoint j){var axis=RobotMath.Frame(j.Axis);if(!ReferenceRobot67.Remote(j)){var motor=Box("NEMA17 · монтажный габарит",j.MotorFrame,j.MotorFrame,-j.GearboxLength-j.Wall-j.MotorLength,j.MotorLength);Add(b,j,"motor",motor,axis,true,"Мотор",false,7850,false,j.MotorMass);Add(b,j,"motor_pilot",MotorRound(j,"Бурт NEMA17",j.MotorPilot,j.MotorPilotHeight,-j.GearboxLength-j.Wall),axis,true,"Мотор",false,7850,false,0);Add(b,j,"motor_shaft",MotorRound(j,"Вал NEMA17",j.MotorShaft,j.MotorShaftLength,-j.GearboxLength-j.Wall),axis,true,"Мотор",false,7850,false,0);}Add(b,j,"bearing",Round("Шариковая опора",j.BearingOuter,j.BearingWidth,j.BearingInner,-j.BearingWidth),axis,true,"Опоры",false,7850);}
 }
 public static class ReferenceRobot67 {
 public static bool Remote(RobotJoint j){int n;return j.BodyGenerator!=null&&j.BodyGenerator.Variant=="Reference67"&&int.TryParse(j.Id.Substring(j.Id.Length-1),out n)&&n>=4;}
 public static RobotDocument Create(double height=1000){var d=IndustrialRobot66.Create();d.Name="Манипулятор по твоему дизайну · новая компоновка";double s=height/1000;var modes=new[]{RobotJointMode.Вращение_Z,RobotJointMode.Вращение_Y,RobotJointMode.Вращение_Y,RobotJointMode.Вращение_X,RobotJointMode.Вращение_Y,RobotJointMode.Вращение_X};double[] angles={0,-10,25,0,15,0};for(int i=0;i<6;i++){var j=d.Joints[i];j.Id="reference67_j"+(i+1);j.ParentId=i==0?null:d.Joints[i-1].Id;j.Mode=modes[i];j.EndX=i==0?80*s:i==2?360*s:i==3?70*s:i==4?70*s:i==5?30*s:0;j.EndZ=i==0?330*s:i==1?450*s:0;j.EndY=0;j.OffsetX=j.OffsetY=0;j.OffsetZ=i==0?120*s:0;j.Position=angles[i];j.GearboxDiameter=i<3?76:50;j.Wall=i<3?6:3.2;j.GearboxLength=i<3?48:32;j.BodyGenerator.Variant="Reference67";j.BodyGenerator.FrameWall=4;j.BodyGenerator.MinWall=3.2;j.BodyGenerator.SkinWall=2.4;j.GeneratedBody=null;}
 return d;}
 public static RobotDocument Cached(){string root=Path.GetDirectoryName(Application.ExecutablePath);string file=Path.Combine(root,"examples","Reference67.robot.json");if(!File.Exists(file))file=Path.Combine(Path.GetDirectoryName(root),"examples","Reference67.robot.json");return File.Exists(file)?RobotDocument.Parse(File.ReadAllText(file)):Create();}
 public static int Scene(string folder){try{var d=RobotDocument.Parse(File.ReadAllText(Path.Combine(folder,"Reference67.robot.json")));var b=RobotCad.Build(d);using(var w=new StreamWriter(Path.Combine(folder,"cad-comparison.obj"),false,new UTF8Encoding(false))){int offset=1,normalOffset=1;foreach(var e in b.Entries.Values.Where(e=>!e.Guide)){var mesh=e.Part.MeshOverride??PrintExport.Mesh(e.Part);var pose=b.Pose(e.Id,0,false);w.WriteLine("o "+e.Id);foreach(var v in mesh.Points){var p=pose.Transform(v);w.WriteLine("v "+p.X.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+" "+p.Y.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+" "+p.Z.ToString("R",System.Globalization.CultureInfo.InvariantCulture));}bool normals=mesh.Normals!=null&&mesh.Normals.Length==mesh.Points.Length;if(normals)foreach(var n in mesh.Normals){var v=pose.Transform(n);if(v.Length>0)v.Normalize();w.WriteLine("vn "+v.X.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+" "+v.Y.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+" "+v.Z.ToString("R",System.Globalization.CultureInfo.InvariantCulture));}for(int i=0;i<mesh.Indices.Length;i+=3){string[] vertices=new string[3];for(int t=0;t<3;t++)vertices[t]=(offset+mesh.Indices[i+t]).ToString()+(normals?"//"+(normalOffset+mesh.Indices[i+t]):"");w.WriteLine("f "+string.Join(" ",vertices));}offset+=mesh.Points.Length;if(normals)normalOffset+=mesh.Normals.Length;}}return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"scene-error.txt"),ex.ToString());return 1;}}
 public static int Generate(string folder){Directory.CreateDirectory(folder);try{string file=Path.Combine(folder,"Reference67.robot.json");var d=File.Exists(file)?RobotDocument.Parse(File.ReadAllText(file)):Create();d.Save(file);using(var k=new CADKernel())foreach(var j in d.Ordered().AsEnumerable().Reverse()){File.AppendAllText(Path.Combine(folder,"progress.txt"),j.Id+"\r\n");if(j.GeneratedBody==null||j.GeneratedBody.Fingerprint!=ProceduralBodySpec.Fingerprint(d,j,j.BodyGenerator)){File.WriteAllText(Path.Combine(folder,"spec-"+j.Id+".json"),CADDocument.Serializer().Serialize(ProceduralBodySpec.Build(d,j,j.BodyGenerator)),Encoding.UTF8);j.GeneratedBody=ProceduralBodySpec.Generate(k,d,j,j.BodyGenerator);d.Save(file);}}var b=RobotCad.Build(d);File.WriteAllText(Path.Combine(folder,"reference67-results.json"),CADDocument.Serializer().Serialize(new{b.Model.Valid,b.Model.Errors,Connections=RobotConnections.Validate(b),Native=d.Joints.Select(j=>new{j.Id,j.GeneratedBody.Result.GeometryValid,j.GeneratedBody.Result.Issues})}),Encoding.UTF8);if(File.Exists(Path.Combine(folder,"reference67-error.txt")))File.Delete(Path.Combine(folder,"reference67-error.txt"));return b.Model.Valid?0:1;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"reference67-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}}
}}

namespace GearLab {public sealed partial class RobotDesignerForm {void OpenReference67(){Replace(ReferenceRobot67.Cached(),null);SetStage(2);notes.AppendText("\r\nНовая компоновка по визуальному образцу. Двигатели кисти перенесены в предплечье. Передача, силовые тяги и секционирование пока требуют разработки; это не допуск к печати всей руки.");}}}
